"use client";

import { useState } from "react";
import { ChevronLeft, ChevronRight, Plus, X } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createCalendarItem } from "@/app/actions/task-actions"; // Doğru fonksiyonu çağırdık
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [type, setType] = useState("agenda");

  // Calender tablosundan gelen verileri tarihlere göre dağıtıyoruz
  const taskMap = initialTasks.reduce((acc: any, item) => {
    // startDatetime artık bir Date objesi olduğu için formatlıyoruz
    const dateKey = format(new Date(item.startDatetime), "yyyy-MM-dd");
    if (!acc[dateKey]) acc[dateKey] = [];
    acc[dateKey].push(item);
    return acc;
  }, {});

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    const payload = {
      titel: title,
      documentType: type,
      datum: format(selectedDate, "yyyy-MM-dd"),
      // userId: "opsiyonel-buradan-da-gonderebilirsin"
    };

    try {
      // DİKKAT: Artık createCalendarItem çağrılıyor!
      const res = await createCalendarItem(payload);
      if (res.success) {
        setTitle("");
        setSelectedDate(null);
        router.refresh(); // Sayfayı yeniler
        window.location.reload(); // Değişikliği garantilemek için
      } else {
        alert("Fout: " + res.error);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1600px] mx-auto px-4 py-10 relative">
      <div className="flex justify-between items-center mb-10 border-b border-white/5 pb-8">
        <h1 className="text-5xl font-black text-white italic tracking-tighter uppercase leading-none">Temporal Grid</h1>
        <div className="flex items-center gap-6 bg-[#0a0e17] border border-white/10 p-2 rounded-xl">
          <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all cursor-pointer"><ChevronLeft size={24} /></button>
          <span className="text-lg font-black text-white w-48 text-center uppercase tracking-widest italic">{format(currentMonth, "MMMM yyyy", { locale: nl })}</span>
          <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all cursor-pointer"><ChevronRight size={24} /></button>
        </div>
      </div>

      <div className="bg-[#0a0e17]/80 border border-white/10 rounded-3xl overflow-hidden shadow-2xl backdrop-blur-xl">
        <div className="grid grid-cols-7 bg-white/5 py-4 border-b border-white/5 text-center font-black text-teal-500/40 text-[10px] uppercase tracking-widest">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => <span key={d}>{d}</span>)}
        </div>
        <div className="grid grid-cols-7">
          {(() => {
            const days = [];
            let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
            const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

            while (day <= endDate) {
              const formattedDate = format(day, "yyyy-MM-dd");
              const dayTasks = taskMap[formattedDate] || [];
              const isCurrentMonth = isSameMonth(day, currentMonth);
              const isToday = isSameDay(day, new Date());
              const currentDay = day;

              days.push(
                <div 
                  key={day.toString()} 
                  onClick={() => setSelectedDate(currentDay)}
                  className={`min-h-[150px] border border-white/5 p-4 transition-all cursor-pointer hover:bg-fuchsia-500/5 relative group ${!isCurrentMonth ? "opacity-10 pointer-events-none" : "opacity-100"}`}
                >
                  <span className={`text-xs font-mono mb-2 block ${isToday ? "text-fuchsia-500 font-black" : "text-teal-500/30"}`}>{format(day, "d")}</span>
                  <div className="space-y-1">
                    {dayTasks.map((t: any) => (
                      <div key={t.id} className={`text-[10px] px-2 py-1.5 truncate rounded border ${t.description === 'agenda' || t.description === 'assignment' ? 'bg-blue-600/10 border-blue-500/30 text-blue-400' : 'bg-fuchsia-600/10 border-fuchsia-500/30 text-fuchsia-400'}`}>
                        {t.title}
                      </div>
                    ))}
                  </div>
                </div>
              );
              day = addDays(day, 1);
            }
            return days;
          })()}
        </div>
      </div>

      {selectedDate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#02040a]/90 backdrop-blur-md px-4">
          <div className="bg-[#0E153A] border border-fuchsia-500/40 p-10 rounded-3xl w-full max-w-md shadow-2xl relative">
            <button onClick={() => setSelectedDate(null)} className="absolute top-6 right-6 text-white/30 hover:text-white cursor-pointer"><X size={28} /></button>
            <h3 className="text-fuchsia-500 font-black uppercase text-[10px] tracking-[0.4em] mb-2">Toevoegen Voor</h3>
            <p className="text-3xl font-black text-white italic tracking-tighter uppercase mb-8">{format(selectedDate, "dd MMMM yyyy", { locale: nl })}</p>
            <div className="space-y-6">
              <input value={title} onChange={(e) => setTitle(e.target.value)} className="w-full bg-[#070B24] border border-white/10 p-5 text-white font-bold rounded-xl outline-none focus:border-fuchsia-500" placeholder="Titel..." />
              <div className="grid grid-cols-2 gap-3">
                {['agenda', 'assignment', 'meeting', 'daily'].map(cat => (
                  <button key={cat} onClick={() => setType(cat)} className={`py-3 text-[10px] font-black uppercase border rounded-lg transition-all ${type === cat ? 'bg-fuchsia-600 border-fuchsia-600 text-white' : 'bg-[#070B24] border-white/5 text-white/40'}`}>
                    {cat}
                  </button>
                ))}
              </div>
              <button onClick={handleSave} disabled={loading || !title} className="w-full bg-white text-[#0E153A] font-black py-5 mt-4 hover:bg-fuchsia-500 hover:text-white transition-all uppercase text-xs tracking-widest rounded-xl">
                {loading ? "Verwerken..." : "Bevestigen"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}